package in.aicon.pocket;
import android.app.*;import android.content.*;
/** Alarm delivery exposes no ledger amount, person name or account on the lock screen. */
public final class ReminderReceiver extends BroadcastReceiver {
 @Override public void onReceive(Context context,Intent intent){if(!"in.aicon.pocket.REMINDER".equals(intent.getAction()))return;if(!ReminderSchedule.prefs(context).getBoolean("enabled",false)||!ReminderSchedule.allowed(context))return;ReminderSchedule.channel(context);Intent open=new Intent(context,QuickActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent tap=PendingIntent.getActivity(context,790,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(context,ReminderSchedule.CHANNEL).setSmallIcon(in.aicon.pocket.test.R.drawable.notification_hisab).setContentTitle("Hisab - a quick check-in").setContentText("Did you forget to update anything? Add your latest entries.").setStyle(new Notification.BigTextStyle().bigText("Did you forget to update anything? Add your latest entries when you have a moment.")).setContentIntent(tap).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).setCategory(Notification.CATEGORY_REMINDER).build();try{context.getSystemService(NotificationManager.class).notify(790,n);}catch(SecurityException ignored){}ReminderSchedule.schedule(context);}
}
